#!/usr/bin/env python3
"""Bind independent native/QEMU trial evidence without claiming board recovery."""
import argparse,hashlib,json,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def sha(p):
 with p.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def ref(p):return {'path':str(p.relative_to(R)),'sha256':sha(p)}
def main():
 p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);a=p.parse_args();native=a.native.resolve();manifest=native/'manifest.json';build=json.loads(manifest.read_text());assert build['status']=='built_readonly_fixture_tests_passed' and build['deployment_gate_enabled'] is False
 packagefile=R/'build/asus-trial-control/package-v1/manifest.json';package=json.loads(packagefile.read_text());deb=R/package['package']['path'];assert sha(deb)==package['package']['sha256'];helper=R/'build/asus-trial-runtime/native-v8';helper_manifest=helper/'manifest.json'
 ack_fixture=R/'build/asus-trial-runtime/qemu-ack-v2/manifest.json';af=json.loads(ack_fixture.read_text());assert af['native_manifest_sha256']==sha(helper_manifest)
 ack_result=R/'build/qemu/asus-trial-ack-kernel10-v2/result.json';ar=json.loads(ack_result.read_text());log=ack_result.parent/'serial.log';text=log.read_text();assert ar['guest_complete'] and not ar['panic'] and ar['initramfs_sha256']==af['initramfs_sha256'] and ar['log_sha256']==sha(log)
 for marker in af['expected_markers']:assert marker in text,marker
 root_report=R/'reports/ubuntu26/squashfs-pivot-guardian-health-v1.json';rr=json.loads(root_report.read_text());assert rr['passed'] and rr['health_identity_fixture']['health_manifest_sha256']==sha(helper_manifest)
 assert rr['health_identity_fixture']['client_sha256']==package['payload']['usr/libexec/leon-asus/trial-health']
 for name,digest in package['payload'].items():assert digest==sha(helper/Path(name).name)
 root_result=R/rr['scenarios'][0]['result']['path'];root_log=root_result.parent/'serial.log';assert sha(root_result)==rr['scenarios'][0]['result']['sha256'] and sha(root_log)==rr['scenarios'][0]['serial_sha256']
 assert '"cases": 34, "all_passed": true' in (native/'fixture-test.log').read_text()
 for marker in ['LAB_TRIAL_WORKER_RESULT_REAP_PASS','LAB_TRIAL_WORKER_EXIT_FAILURE_LATCH_PASS','LAB_TRIAL_WORKER_TIMEOUT_NO_OVERLAP_REAP_PASS']:assert marker in (native/'worker-test.log').read_text()
 assert 'INTERP' not in (native/'guardian-elf.txt').read_text() and 'NEEDED' not in (native/'guardian-elf.txt').read_text()
 out=R/'build/asus-trial-runtime/source-audit';out.mkdir(exist_ok=True)
 vendor=R/'build/kernel9-ui1-rootfs/lib/libbcm_flashutil.so'
 for name,start,stop in [('getBootReason','0xba10','0xbb24'),('GPT_getBootImageState','0xcbf0','0xcc1c')]:
  target=out/(name+'.txt');target.write_text(subprocess.check_output(['objdump','-d','--start-address='+start,'--stop-address='+stop,str(vendor)],text=True))
 source_evidence=[R/'source/release/src-rt-5.04behnd.4916/bcmdrivers/opensource/char/bcm_bootstate/impl1/bcm_bootstate.c',R/'source/release/src-rt-5.04behnd.4916/bcmdrivers/opensource/include/bcm963xx/bcm_bootstate.h',R/'source/release/src-rt-5.04behnd.4916/bootloaders/u-boot-2019.07/board/broadcom/bcmbca/sdk_test_commands.c',vendor,out/'getBootReason.txt',out/'GPT_getBootImageState.txt']
 evidence={'native_build':ref(manifest),'readonly_preflight_tests':ref(native/'fixture-test.log'),'worker_lifecycle_tests':ref(native/'worker-test.log'),'sha256_ack_parser_tests':ref(native/'adapter-test.log'),'ack_qemu_result':ref(ack_result),'ack_qemu_serial':ref(log),'root_identity_qemu_result':ref(root_result),'root_identity_qemu_serial':ref(root_log)}
 package['root_guardian_auth_fixture_pending']=False;package['component_validation_passed']=True;package['runtime_accepted']=False;package['validation_evidence']={k:v for k,v in evidence.items() if 'qemu' in k};packagefile.write_text(json.dumps(package,indent=2)+'\n')
 result={'schema_version':1,'status':'native_preflight_and_trial_clients_validated_production_guardian_gated','deployment_gate_enabled':False,'runtime_accepted':False,'hardware_watchdog_opened':False,'hardware_reset_proven':False,'router_accessed':False,'automatic_commit_allowed':False,'evidence':evidence,'package_manifest':ref(packagefile),'package':package['package'],'checks':{'readonly_preflight_cases':34,'known_sha256_and_uint64_parser_passed':True,'worker_real_fork_sigkill_reap_cases':3,'real_ssh_ack_markers':af['expected_markers'],'immutable_guardian_identity_current_boot_and_forged_root_server':True,'static_guardian_no_interpreter_or_needed':True,'empty_environment_refusal':True},'bootstate_audit':{'sources':[ref(x) for x in source_evidence],'exact_vendor_semantics':'GPT COMMITTED2 branch calls getBootReason, which returns raw hexadecimal strtoul unchanged; compares full value with integer1 and selects PART2 when different. It does not mask to the low nibble.','conservative_candidate_semantics':'Require <=16bit hexadecimal, known current reason0,2,4 and phase0x00..0x60; reject ACTIVATE nibble1 even with phase/history bits. Upper byte is preserved history. This is intentionally stricter than vendor, and may refuse an unexpected first-trial encoding.','observed_raw':'134 (no newline), from separately recorded read-only current kernel9 capture; not presumed exact future kernel10 startup value.','seq_bound':'Primary SDK sets newly written image seq=(other+1)%1000; accept canonical decimal0..999; never compile current5,4.','token':'/etc/leon/trial-slot-proof root0600, exact5-line schema. Requires final postflash metadata fullhash + pinned full stock p5/p6 hashes; no token generated by these scripts.'},'production_guardian':{'binary':ref(native/'guardian-integrated'),'source_snapshot':str((native/'source-snapshot').relative_to(R)),'scope':'Source includes two-phase preflight/arm/exec/confirmed-abort, native worker health, authenticated ACK and immutable ownership query, metadata recheck, sole hardware adapter. Compile-time deployment gate is fixedfalse.','startup_grace_seconds':300,'prearm_deadline_seconds':15,'arm_ack_deadline_seconds':3,'hardware_timeout_seconds':40,'external_lease_seconds':60,'collector_limit_ms':6500,'source_peer_fixes':['Verified proc SysRq b before last-resort reboot syscall; fallback cannot claim watchdog preservation.','Retain worker PID until actual nonblocking reap; failure prevents overlapping replacement.','Canonical active sshd argv/private config check required in addition to -T.']},'remaining':['Final candidate exact critical-file composition and whole integrated production collector tests under kernel10.','Verify actual kernel10 /sys/kernel/notes equals pinned vmlinux notes section.','Device-local selected-account migration and individual host keys; trusted observer hostkey provisioning.','Final postflash fresh slot token plus first-trial reset-reason semantics.','Explicit deployment gate activation only after review; sole-owner hardware readback/reset/stock-slot fallback remains physically unproven.','Real ASUS Wi-Fi/AiMesh/AI hardware behavior is not proved by broker READY or these SSH tests.'],'checker_sha256':sha(Path(__file__))}
 (R/'reports/ubuntu26/asus-trial-runtime.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'preflight_cases':34,'hardware_proven':False,'package':package['package']['path']},indent=2))
if __name__=='__main__':main()
